CREATE PUBLICATION orders_pub FOR TABLE orders, order_items;
-- on subscriber (17)
CREATE SUBSCRIPTION orders_sub
  CONNECTION 'host=pg16 dbname=shop user=repl'
  PUBLICATION orders_pub;

SELECT relname, n_dead_tup, last_autovacuum
FROM pg_stat_user_tables ORDER BY n_dead_tup DESC LIMIT 5;
VACUUM (VERBOSE, ANALYZE) orders;

CREATE INDEX CONCURRENTLY orders_customer_idx ON orders (customer_id);
-- check for leftovers from a failed build
SELECT indexrelid::regclass FROM pg_index WHERE NOT indisvalid;

-- release 1 (expand)
ALTER TABLE users ADD COLUMN email_address text;
-- app writes both columns; backfill in batches
UPDATE users SET email_address = email WHERE id BETWEEN 1 AND 10000;
-- release 3 (contract)
ALTER TABLE users DROP COLUMN email;

SET lock_timeout = '5s';
ALTER TABLE orders ADD CONSTRAINT fk_customer
  FOREIGN KEY (customer_id) REFERENCES customers (id) NOT VALID;
ALTER TABLE orders VALIDATE CONSTRAINT fk_customer;  -- SHARE UPDATE EXCLUSIVE only

