SELECT archived_count, failed_count, last_failed_wal FROM pg_stat_archiver;
SELECT slot_name, active, wal_status, safe_wal_size FROM pg_replication_slots;
SELECT pg_drop_replication_slot('old_replica');
ALTER SYSTEM SET max_slot_wal_keep_size = '50GB';

SELECT client_addr, state,
  pg_wal_lsn_diff(sent_lsn, replay_lsn) AS replay_lag_bytes,
  write_lag, flush_lag, replay_lag
FROM pg_stat_replication;
-- on replica
SELECT now() - pg_last_xact_replay_timestamp() AS lag;

SELECT pid, state, now() - xact_start AS age, query
FROM pg_stat_activity WHERE pid = ANY (
  SELECT unnest(pg_blocking_pids(pid)) FROM pg_stat_activity WHERE wait_event_type = 'Lock');
